import { CommonModule } from '@angular/common';
import { HttpErrorResponse } from '@angular/common/http';
import { Component, HostListener, OnDestroy, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, RouterLink, RouterLinkActive } from '@angular/router';
import { CuiAlertComponent, CuiCardComponent } from '@certinal/ui';
import { authoringDocument, SmartIntakeApiService } from '../../smart-intake-api.service';
import { AuthoringComment, AuthoringDocument, AuthoringImportCandidate, ContentSettings, LocaleReview, PresenceMember, PreviewResult, ReusableComponent, SpeechResult, SupportedAuthoringLocale, ThemeSettings } from './authoring.types';
import { AuthoringStore } from './authoring.store';
import { StaffSessionStore } from '../../core/m5-session.store';
import { authoringStorageKey } from '../../core/authoring-cache';

type AuthoringTab = 'author' | 'preview' | 'history' | 'import' | 'components' | 'theme' | 'content';
type AuthoringResourceState = 'loading' | 'ready' | 'denied' | 'expired' | 'offline' | 'error';

@Component({
  selector: 'app-authoring-page',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, RouterLinkActive, CuiCardComponent, CuiAlertComponent],
  template: `
    <main class="authoring" [attr.dir]="content().locale === 'ar' ? 'rtl' : 'ltr'" data-testid="authoring-page">
      <header class="authoring__header">
        <div>
          <p class="type-caption-bold authoring__eyebrow">SMART INTAKE · AUTHORING</p>
          <h1 class="type-h3">{{store.document().title}}</h1>
          <p class="type-caption">Draft revision {{store.document().revision}} · Stable canonical IDs</p>
        </div>
        <div class="authoring__actions" aria-label="Draft actions">
          <button class="authoring__button" type="button" [disabled]="!store.canUndo()" (click)="undo()">Undo</button>
          <button class="authoring__button" type="button" [disabled]="!store.canRedo()" (click)="redo()">Redo</button>
          <button class="authoring__button authoring__button--primary" type="button" [disabled]="saving()" (click)="save()">{{saving() ? 'Saving…' : 'Save changes'}}</button>
        </div>
      </header>

      <nav class="authoring__tabs" aria-label="Authoring tools">
        <a *ngFor="let item of tabs" [routerLink]="routeFor(item.id)" routerLinkActive="is-active" [routerLinkActiveOptions]="{ exact: item.id === 'author' }">{{item.label}}</a>
      </nav>

      <cui-alert *ngIf="store.conflict() as conflict" variant="warning" title="Revision conflict">
        <p>{{conflict.message}} Both client and server documents remain available until you resolve this.</p>
        <div class="authoring__inline-actions">
          <button class="authoring__button" type="button" (click)="resolve('server')">Use server version</button>
          <button class="authoring__button authoring__button--primary" type="button" (click)="resolve('client')">Keep my version</button>
        </div>
      </cui-alert>

      <cui-alert *ngIf="notice()" variant="info" title="Authoring update"><p>{{notice()}}</p></cui-alert>

      <cui-alert *ngIf="resourceState() === 'denied'" variant="error" title="Authoring access denied"><p>Your session cannot access this draft. Cached authoring data was cleared.</p></cui-alert>
      <cui-alert *ngIf="resourceState() === 'expired'" variant="warning" title="Session expired"><p>Sign in again to continue. Cached authoring data was cleared.</p></cui-alert>
      <cui-alert *ngIf="resourceState() === 'offline'" variant="warning" title="Working offline"><p>The network is unavailable. Only the local draft fallback is shown.</p></cui-alert>
      <cui-alert *ngIf="resourceState() === 'error'" variant="error" title="Authoring unavailable"><p>The server could not load this draft. Cached content is not shown for this response.</p></cui-alert>

      <section *ngIf="resourceState() === 'ready' || resourceState() === 'offline'">
      <section *ngIf="tab() === 'author'" class="authoring__workspace" aria-label="Three pane form editor">
        <aside class="authoring__pane authoring__outline" aria-label="Form hierarchy">
          <div class="authoring__pane-head"><h2 class="type-label">FORM STRUCTURE</h2><button class="authoring__link" type="button" (click)="addPhase()">Add phase</button></div>
          <div class="authoring__tree" role="tree" (keydown)="onTreeKeydown($event)">
            <ng-container *ngFor="let phase of store.document().phases">
              <button class="authoring__tree-item authoring__tree-item--phase" role="treeitem" [attr.data-authoring-id]="phase.id" [class.is-selected]="store.selectedId() === phase.id" (click)="select(phase.id)">{{phase.title}}</button>
              <ng-container *ngFor="let page of phase.pages">
                <button class="authoring__tree-item authoring__tree-item--page" role="treeitem" [attr.data-authoring-id]="page.id" [class.is-selected]="store.selectedId() === page.id" (click)="select(page.id)">{{page.title}}</button>
                <ng-container *ngFor="let section of page.sections">
                  <button class="authoring__tree-item authoring__tree-item--section" role="treeitem" [attr.data-authoring-id]="section.id" [class.is-selected]="store.selectedId() === section.id" (click)="select(section.id)">{{section.title}}</button>
                  <button *ngFor="let node of section.nodes" class="authoring__tree-item authoring__tree-item--node" role="treeitem" [attr.data-authoring-id]="node.id" [class.is-selected]="store.selectedId() === node.id" (click)="select(node.id)">{{node.label}}</button>
                </ng-container>
              </ng-container>
            </ng-container>
          </div>
        </aside>

        <section class="authoring__canvas" aria-live="polite">
          <div class="authoring__pane-head"><div><p class="type-caption">FOCUSED EDITING</p><h2 class="type-h4">{{selectedLabel()}}</h2></div><button class="authoring__button" type="button" (click)="addToSelection()">Add</button></div>
          <cui-card *ngFor="let group of selectedGroups()" [accentLeft]="true" accentColor="emerald" class="authoring__group">
            <p class="type-caption-bold">{{group.title}}</p>
            <article *ngFor="let node of group.nodes" class="authoring__node" [class.is-selected]="store.selectedId() === node.id" tabindex="0" (focus)="select(node.id)" (click)="select(node.id)">
              <div><h3 class="type-label">{{node.label}}</h3><p class="type-caption">{{node.kind}} · {{node.control ?? node.componentVersion ?? 'content'}}</p></div>
              <button class="authoring__link" type="button" (click)="removeNode(node.id); $event.stopPropagation()">Remove</button>
            </article>
          </cui-card>
          <cui-card *ngIf="!selectedGroups().length"><p>Select a phase, page, section, or node in the outline to edit it here.</p></cui-card>
        </section>

        <aside class="authoring__pane authoring__inspector" aria-label="Selected element inspector">
          <h2 class="type-label">INSPECTOR</h2>
          <label class="authoring__label">Label <input [(ngModel)]="renameValue" (keyup.enter)="rename()" [placeholder]="selectedLabel()"></label>
          <button class="authoring__button" type="button" (click)="rename()">Rename</button>
          <section class="authoring__inspection"><h3 class="type-label">EXPRESSION</h3><p class="type-caption">Build expressions with canonical references. Explanations expose dependencies and impact before save.</p><textarea [(ngModel)]="expressionText" aria-label="Expression builder" placeholder="if(answer('field-id'), …)"></textarea><button class="authoring__link" type="button" (click)="explainExpression()">Explain expression</button></section>
          <section class="authoring__inspection"><h3 class="type-label">IMPACT</h3><p class="type-caption" *ngFor="let impact of currentImpact()">{{impact}}</p></section>
          <section class="authoring__inspection"><h3 class="type-label">COMMENTS</h3><p class="type-caption" *ngFor="let comment of commentsForSelection()"><strong>{{comment.author}}</strong> · {{comment.body}}</p><label class="authoring__label">Comment <textarea [(ngModel)]="commentText" aria-label="Comment"></textarea></label><button class="authoring__link" type="button" (click)="sendComment()">Add comment</button></section>
          <section class="authoring__inspection"><h3 class="type-label">COLLABORATORS</h3><p class="type-caption" *ngFor="let member of presence()">{{member.displayName}}<span *ngIf="member.selectedId"> · editing {{member.selectedId}}</span></p></section>
        </aside>
      </section>

      <section *ngIf="tab() === 'preview'" class="authoring__tool"><h2 class="type-h4">Ordinary author preview</h2><p>This uses the M7 authoring preview endpoint with synthetic answers only. It does not start respondent sessions, submit data, publish, email, webhook, or call speech providers.</p><label class="authoring__label">Preview locale<select [ngModel]="content().locale" (ngModelChange)="setLocale($event)"><option *ngFor="let locale of locales" [ngValue]="locale">{{localeName(locale)}}</option></select></label><label class="authoring__label">Synthetic answers (JSON)<textarea [(ngModel)]="previewAnswers" aria-label="Synthetic preview answers"></textarea></label><button class="authoring__button authoring__button--primary" type="button" (click)="preview()">Run preview</button><pre *ngIf="previewResult()">{{previewResult() | json}}</pre></section>

      <section *ngIf="tab() === 'history'" class="authoring__tool"><h2 class="type-h4">Command history and semantic diff</h2><p class="type-caption">Undo and redo retain at least 100 commands locally and are reconciled with persisted server history.</p><ol><li *ngFor="let entry of store.history()"><strong>{{entry.label}}</strong> <span>{{entry.at | date:'short'}}</span><p *ngFor="let impact of entry.impact">{{impact}}</p></li></ol></section>

          <section *ngIf="tab() === 'import'" class="authoring__tool"><h2 class="type-h4">Strict import candidate</h2><p>Validate first. Commit requires the candidate digest and current draft revision, preserving UPDATE IDs or remapping COPY IDs server-side.</p><input type="file" accept="application/json" aria-label="Import package" (change)="readImport($event)"><pre *ngIf="importValidation()">{{importValidation() | json}}</pre><div class="authoring__inline-actions"><button class="authoring__button" type="button" [disabled]="!importCandidate()" (click)="validateImport()">Validate candidate</button><button class="authoring__button" type="button" [class.authoring__button--primary]="importMode === 'UPDATE'" (click)="importMode = 'UPDATE'">Update IDs</button><button class="authoring__button" type="button" [class.authoring__button--primary]="importMode === 'COPY'" (click)="importMode = 'COPY'">Copy with new IDs</button><button class="authoring__button authoring__button--primary" type="button" [disabled]="!canCommitImport()" (click)="commitImport()">Commit candidate</button></div></section>

      <section *ngIf="tab() === 'components'" class="authoring__tool"><h2 class="type-h4">Reusable components</h2><p>Insertion pins the selected reusable component version in the canonical document.</p><cui-card *ngFor="let component of components()" [accentTop]="true" accentColor="cyan"><h3 class="type-label">{{component.name}} <span class="type-caption">v{{component.version}}</span></h3><p>{{component.description}}</p><button class="authoring__button" type="button" (click)="insertComponent(component)">Insert in selected section</button></cui-card></section>

      <section *ngIf="tab() === 'theme'" class="authoring__tool"><h2 class="type-h4">Theme tokens and preflight</h2><label class="authoring__label">Preset <input [(ngModel)]="theme().preset"></label><label class="authoring__label">Tokens (JSON)<textarea [(ngModel)]="themeTokensText" aria-label="Theme tokens"></textarea></label><p class="type-caption">Locked tokens: {{theme().locks.join(', ') || 'None'}}</p><cui-alert *ngFor="let item of theme().preflight" [variant]="item.severity === 'error' ? 'error' : 'warning'" [title]="item.code"><p>{{item.message}}</p></cui-alert><button class="authoring__button authoring__button--primary" type="button" (click)="saveTheme()">Save bounded theme</button></section>

      <section *ngIf="tab() === 'content'" class="authoring__tool"><h2 class="type-h4">Governed guidance and localization</h2>
        <div class="authoring__locale" role="group" aria-label="Content language"><button *ngFor="let locale of locales" class="authoring__button" [class.authoring__button--primary]="content().locale === locale" type="button" (click)="setLocale(locale)">{{localeName(locale)}} <span>· {{localeStructuralState(locale)}}</span></button></div>
        <p class="type-caption">Locale state reflects only server-provided bundles and review records. A missing locale is not synthesized in the draft.</p>
        <section class="authoring__inspection"><h3 class="type-label">Guidance references</h3><p class="type-caption">The package stores only stable ID and message-key references. Localized text is saved separately in the selected locale bundle.</p><label class="authoring__label">Brief guidance<textarea [(ngModel)]="briefGuidanceText"></textarea></label><label class="authoring__label">Detailed guidance<textarea [(ngModel)]="detailedGuidanceText"></textarea></label><label class="authoring__label">Glossary (JSON)<textarea [(ngModel)]="glossaryText"></textarea></label><label class="authoring__label">Questions and answers (JSON)<textarea [(ngModel)]="questionsAndAnswersText"></textarea></label><label class="authoring__label">Narration<textarea [(ngModel)]="narrationText"></textarea></label><label class="authoring__label">Additional canonical references (JSON object)<textarea [(ngModel)]="referencesText"></textarea></label><button class="authoring__button authoring__button--primary" type="button" (click)="saveGuidance()">Save guidance references</button></section>
        <section class="authoring__inspection"><h3 class="type-label">Translation scope · {{localeName(content().locale)}}</h3><p class="type-caption">Save the brief, detailed, glossary, Q&A, and narration text above into this locale’s translation messages.</p><button class="authoring__button authoring__button--primary" type="button" (click)="saveTranslations()">Save locale text</button></section>
        <section class="authoring__inspection"><h3 class="type-label">Reviewer approval</h3><p class="type-caption" *ngFor="let review of content().localeReviews">{{localeName(review.locale)}} · {{review.status}} · revision {{review.sourceRevision}}</p><button class="authoring__button authoring__button--primary" type="button" [disabled]="!canApproveLocales()" (click)="approveLocales()">{{approvalLabel()}}</button><p *ngIf="!isReviewer()" class="type-caption">Only reviewers can approve or reapprove locale bundles.</p></section>
        <section class="authoring__inspection"><h3 class="type-label">Speech</h3><div class="authoring__speech"><button class="authoring__button" type="button" [disabled]="speechBusy() || !narrationText.trim()" (click)="toggleNarration()">{{speechBusy() ? 'Preparing…' : speechPlaying() ? 'Pause' : 'Play'}}</button><button class="authoring__button" type="button" [disabled]="speechBusy() || speechCapturing()" (click)="startQuestionCapture()">Click to Ask</button><button *ngIf="speechCapturing()" class="authoring__button" type="button" (click)="finishQuestionCapture()">Finish</button><button *ngIf="speechCapturing()" class="authoring__button" type="button" (click)="cancelQuestionCapture()">Cancel</button><span class="type-caption">{{speechStatus()}}</span></div></section>
      </section>
      </section>
    </main>
  `,
  styles: [`
    .authoring{max-width:100%;padding:var(--spacing-6);color:var(--color-text-primary)} .authoring__header,.authoring__pane-head,.authoring__actions,.authoring__inline-actions,.authoring__tabs,.authoring__locale,.authoring__speech{display:flex;align-items:center;gap:var(--spacing-3)} .authoring__header{justify-content:space-between;flex-wrap:wrap;margin-bottom:var(--spacing-4)} .authoring__eyebrow{color:var(--color-emerald-700);margin:0}.authoring__tabs{overflow:auto;border-bottom:var(--border-1) solid var(--color-border-default);margin-bottom:var(--spacing-5)}.authoring__tabs a{padding:var(--spacing-3);color:var(--color-text-muted);text-decoration:none;white-space:nowrap}.authoring__tabs a.is-active{color:var(--color-emerald-700);border-bottom:var(--border-2) solid var(--color-emerald-600)}.authoring__button,.authoring__link{border:var(--border-1) solid var(--color-border-strong);border-radius:var(--radius-full);background:var(--color-bg-surface);padding:var(--spacing-2) var(--spacing-4);color:var(--color-text-primary)}.authoring__button--primary{background:var(--color-emerald-600);border-color:var(--color-emerald-600);color:var(--color-text-inverse)}.authoring__button:disabled{opacity:.55;cursor:not-allowed}.authoring__link{border:0;background:transparent;color:var(--color-emerald-700);padding:var(--spacing-1)}.authoring__workspace{display:grid;grid-template-columns:minmax(13rem,1fr) minmax(24rem,2.5fr) minmax(16rem,1fr);gap:var(--spacing-4);min-height:calc(100vh - 16rem)}.authoring__pane,.authoring__canvas,.authoring__tool{background:var(--color-bg-surface);border:var(--border-1) solid var(--color-border-default);border-radius:var(--radius-xl);padding:var(--spacing-4)}.authoring__tree{display:grid;gap:var(--spacing-1)}.authoring__tree-item{border:0;background:transparent;text-align:start;padding:var(--spacing-2);border-radius:var(--radius-md);color:var(--color-text-primary)}.authoring__tree-item:focus-visible,.authoring__node:focus-visible{outline:var(--border-3) solid var(--color-emerald-400);outline-offset:var(--spacing-1)}.authoring__tree-item.is-selected,.authoring__node.is-selected{background:var(--color-emerald-50)}.authoring__tree-item--page{padding-inline-start:var(--spacing-5)}.authoring__tree-item--section{padding-inline-start:var(--spacing-7)}.authoring__tree-item--node{padding-inline-start:var(--spacing-9)}.authoring__canvas{display:grid;align-content:start;gap:var(--spacing-4)}.authoring__group{display:block}.authoring__node{display:flex;justify-content:space-between;gap:var(--spacing-3);padding:var(--spacing-3);border-top:var(--border-1) solid var(--color-border-default);cursor:pointer}.authoring__label{display:grid;gap:var(--spacing-1);margin-bottom:var(--spacing-3)}.authoring input,.authoring textarea{width:100%;border:var(--border-1) solid var(--color-border-strong);border-radius:var(--radius-md);padding:var(--spacing-2);background:var(--color-bg-surface);color:var(--color-text-primary)}.authoring textarea{min-height:5rem}.authoring__inspection{padding-top:var(--spacing-4);margin-top:var(--spacing-4);border-top:var(--border-1) solid var(--color-border-default)}.authoring__tool{max-width:55rem;margin:auto;display:grid;gap:var(--spacing-4)}.authoring__tool pre{white-space:pre-wrap;overflow:auto;background:var(--color-bg-subtle);padding:var(--spacing-3);border-radius:var(--radius-md)}@media (max-width:1100px){.authoring__workspace{grid-template-columns:1fr}.authoring__outline{max-height:18rem;overflow:auto}.authoring__inspector{order:3}}@media (max-width:500px){.authoring{padding:var(--spacing-3)}.authoring__header{align-items:flex-start}.authoring__actions{width:100%;flex-wrap:wrap}.authoring__button{flex:1}.authoring__tabs{margin-inline:calc(var(--spacing-3) * -1)}}
  `],
})
export class AuthoringPageComponent implements OnDestroy {
  readonly store = inject(AuthoringStore);
  private readonly api = inject(SmartIntakeApiService);
  private readonly route = inject(ActivatedRoute);
  private readonly session = inject(StaffSessionStore);
  readonly tabs: readonly { id: AuthoringTab; label: string }[] = [{ id: 'author', label: 'Author' }, { id: 'preview', label: 'Preview' }, { id: 'history', label: 'History' }, { id: 'import', label: 'Import' }, { id: 'components', label: 'Components' }, { id: 'theme', label: 'Theme' }, { id: 'content', label: 'Content' }];
  readonly locales = ['en', 'hi', 'ar'] as const;
  readonly saving = signal(false); readonly notice = signal(''); readonly previewResult = signal<PreviewResult | null>(null); readonly importCandidate = signal<unknown | null>(null); readonly importValidation = signal<AuthoringImportCandidate | null>(null); readonly components = signal<readonly ReusableComponent[]>([]); readonly comments = signal<readonly AuthoringComment[]>([]); readonly presence = signal<readonly PresenceMember[]>([]);
  readonly resourceState = signal<AuthoringResourceState>('loading'); readonly speechBusy = signal(false); readonly speechPlaying = signal(false); readonly speechCapturing = signal(false); readonly speechStatus = signal('Speech is unavailable until an approved provider is configured.');
  readonly theme = signal<ThemeSettings>({ preset: 'Certinal', tokens: {}, locks: [], preflight: [] });
  readonly content = signal<ContentSettings>({ locale: 'en', translations: {}, guidance: {}, localeReviews: [] });
  renameValue = ''; expressionText = ''; commentText = ''; previewAnswers = '{\n  "field-name": "Ada Lovelace"\n}'; themeTokensText = '{}'; briefGuidanceText = ''; detailedGuidanceText = ''; glossaryText = '{}'; questionsAndAnswersText = '[]'; narrationText = ''; referencesText = '{}'; importMode: 'UPDATE' | 'COPY' = 'UPDATE'; private heartbeat?: ReturnType<typeof setInterval>; private audio?: HTMLAudioElement; private recognition?: BrowserSpeechRecognition; private capturedQuestion = ''; private preserveContentInputs = false;

  constructor() { this.load(); this.heartbeat = setInterval(() => this.refreshCollaboration(), 30_000); }
  ngOnDestroy(): void { if (this.heartbeat) clearInterval(this.heartbeat); this.cancelQuestionCapture(); this.stopAudio(); }
  tab(): AuthoringTab { const child = this.route.firstChild?.snapshot.data['authoringTab'] as AuthoringTab | undefined; return child ?? 'author'; }
  routeFor(tab: AuthoringTab): string[] { const base = ['/workspaces', this.workspaceId(), 'forms', this.formId(), 'drafts', this.draftId(), 'author']; return tab === 'author' ? base : [...base, tab]; }
  selectedLabel(): string { const selected = this.selectedItem(); return selected?.label ?? selected?.title ?? 'Form'; }
  selectedGroups() { const selected = this.store.selectedId(); return this.store.document().phases.flatMap((phase) => phase.pages.flatMap((page) => page.sections.filter((section) => [phase.id, page.id, section.id, ...section.nodes.map((node) => node.id)].includes(selected ?? '')).map((section) => ({ title: `${phase.title} / ${page.title} / ${section.title}`, nodes: section.nodes })))); }
  currentImpact(): readonly string[] { return this.store.history().at(0)?.impact ?? ['No unreviewed dependency impact.']; }
  commentsForSelection(): readonly AuthoringComment[] { return this.comments().filter((comment) => comment.targetId === this.store.selectedId()); }
  select(id: string): void { this.cancelQuestionCapture(); this.stopAudio(); this.store.select(id); this.renameValue = this.selectedLabel(); this.api.updateAuthoringPresence(this.workspaceId(), this.formId(), this.draftId(), id).subscribe({ error: () => undefined }); }
  addPhase(): void { this.localCommand({ type: 'add-phase', label: 'New phase' }); }
  addToSelection(): void { const selection = this.selectedItem(); if (!selection) return; if ('pages' in selection) this.localCommand({ type: 'add-page', targetId: selection.id, label: 'New page' }); else if ('sections' in selection) this.localCommand({ type: 'add-section', targetId: selection.id, label: 'New section' }); else { const section = this.containingSection(selection.id); if (section) this.localCommand({ type: 'add-node', targetId: section.id, label: 'New field', node: { id: crypto.randomUUID(), kind: 'field', label: 'New field', control: 'text' } }); } }
  rename(): void { const id = this.store.selectedId(); if (id && this.renameValue.trim()) this.localCommand({ type: 'rename', targetId: id, label: this.renameValue }); }
  removeNode(id: string): void { this.localCommand({ type: 'remove-node', targetId: id, label: 'Remove field' }); }
  explainExpression(): void { this.notice.set(this.expressionText.trim() ? `Expression explanation: references are resolved by stable canonical ID; check fields listed in Impact before save.` : 'Enter an expression to see its canonical reference explanation.'); }
  sendComment(): void { const targetId = this.store.selectedId(); const body = this.commentText.trim(); if (!targetId || !body) return; const identity = stableOperationIdentity({ body, targetId }); const key = this.store.operationKey(this.storageKey(), 'comment', identity); this.api.addAuthoringComment(this.workspaceId(), this.formId(), this.draftId(), body, targetId, key).subscribe({ next: (comment) => { this.comments.update((comments) => [comment, ...comments]); this.commentText = ''; this.store.completeOperation(this.storageKey(), 'comment', identity); }, error: (error) => this.handleError(error) }); }
  undo(): void { if (this.store.pendingCommands().length) { this.store.undo(this.storageKey()); return; } this.api.authoringUndo(this.workspaceId(), this.formId(), this.draftId(), this.store.document().revision, this.store.operationKey(this.storageKey(), 'undo', String(this.store.document().revision))).subscribe({ next: (server) => { this.acceptRevision(server); this.reloadHistory(); }, error: (error) => this.handleError(error) }); }
  redo(): void { if (this.store.redoPendingCommands().length) { this.store.redo(this.storageKey()); return; } this.api.authoringRedo(this.workspaceId(), this.formId(), this.draftId(), this.store.document().revision, this.store.operationKey(this.storageKey(), 'redo', String(this.store.document().revision))).subscribe({ next: (server) => { this.acceptRevision(server); this.reloadHistory(); }, error: (error) => this.handleError(error) }); }
  save(): void { if (!this.store.pendingCommands().length) { this.notice.set('All changes are already saved.'); return; } this.saving.set(true); this.api.authoringCommands(this.workspaceId(), this.formId(), this.draftId(), this.store.document().revision, this.store.document(), this.store.pendingCommands(), this.store.commandBatchKey(this.storageKey())).subscribe({ next: (document) => { this.acceptRevision(document); this.reloadHistory(); this.notice.set('Canonical draft saved.'); this.saving.set(false); }, error: (error) => { this.saving.set(false); this.handleError(error); } }); }
  resolve(resolution: 'client' | 'server'): void { const conflict = this.store.conflict(); if (!conflict?.id) return; const definition = resolution === 'client' ? conflict.client.definition : conflict.server.definition; this.api.resolveAuthoringConflict(this.workspaceId(), this.formId(), this.draftId(), conflict.server.revision, conflict.id, definition, this.store.operationKey(this.storageKey(), 'resolve', stableOperationIdentity({ revision: conflict.server.revision, conflictId: conflict.id, definition }))).subscribe({ next: (document) => { this.acceptRevision(document); this.reloadHistory(); }, error: (error) => this.handleError(error) }); }
  preview(): void { let answers: Record<string, unknown>; try { answers = JSON.parse(this.previewAnswers) as Record<string, unknown>; } catch { this.notice.set('Synthetic answers must be valid JSON.'); return; } this.api.authoringPreview(this.workspaceId(), this.formId(), this.draftId(), answers, this.content().locale).subscribe({ next: (result) => { this.previewResult.set(result); this.notice.set('Preview completed through the authoring endpoint with no respondent side effects.'); }, error: (error) => this.handleError(error) }); }
  readImport(event: Event): void { this.importCandidate.set(null); this.importValidation.set(null); const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 1_000_000) { this.notice.set('Import files must be 1 MB or smaller.'); return; } file.text().then((text) => { try { this.importCandidate.set(JSON.parse(text)); } catch { this.notice.set('The selected import is not valid JSON.'); } }); }
  validateImport(): void { const candidate = this.importCandidate(); if (candidate) this.api.validateAuthoringImport(this.workspaceId(), this.formId(), this.draftId(), candidate).subscribe({ next: (result) => this.importValidation.set(result), error: (error) => this.handleError(error) }); }
  canCommitImport(): boolean { const candidate = this.importValidation(); return candidate?.state === 'VALID' && candidate.baseRevision === this.store.document().revision; }
  commitImport(): void { const candidate = this.importValidation(); if (!this.canCommitImport() || !candidate) { this.notice.set('Validate a current valid import candidate before committing.'); return; } const identity = `${candidate.candidateId}:${candidate.digest}:${this.importMode}`; this.api.commitAuthoringImport(this.workspaceId(), this.formId(), this.draftId(), this.store.document().revision, candidate, this.importMode, this.store.operationKey(this.storageKey(), 'import', identity)).subscribe({ next: (document) => { this.acceptRevision(document); this.notice.set('Validated candidate committed.'); this.reloadHistory(); }, error: (error) => this.handleError(error) }); }
  insertComponent(component: ReusableComponent): void { const section = this.containingSection(this.store.selectedId()); const path = section && this.componentInsertionPath(section.id); if (!section || !path) { this.notice.set('Select a canonical section before inserting a component.'); return; } const revision = this.store.document().revision; this.saving.set(true); this.api.insertAuthoringComponent(this.workspaceId(), this.formId(), this.draftId(), revision, component, path, this.store.componentInsertionKey(this.storageKey(), revision, component.key, path)).subscribe({ next: (document) => { this.acceptRevision(document); this.notice.set(`${component.name} inserted as a version-pinned component.`); this.saving.set(false); }, error: (error) => { this.saving.set(false); this.handleError(error); } }); }
  saveTheme(): void { try { this.theme.update((theme) => ({ ...theme, tokens: JSON.parse(this.themeTokensText) as Record<string, string> })); } catch { this.notice.set('Theme tokens must be a JSON object.'); return; } const revision = this.store.document().revision; const theme = this.theme(); this.api.updateAuthoringTheme(this.workspaceId(), this.formId(), this.draftId(), revision, theme, this.store.operationKey(this.storageKey(), 'theme', stableOperationIdentity({ revision, theme }))).subscribe({ next: (updated) => { this.theme.set(updated); if (updated.document) this.acceptRevision(updated.document); this.notice.set('Bounded theme saved and preflight refreshed.'); }, error: (error) => this.handleError(error) }); }
  setLocale(locale: SupportedAuthoringLocale): void { this.cancelQuestionCapture(); this.stopAudio(); this.content.update((value) => ({ ...value, locale })); this.populateContentEditors(this.content()); }
  localeName(locale: SupportedAuthoringLocale): string { return locale === 'en' ? 'English' : locale === 'hi' ? 'हिन्दी' : 'العربية'; }
  localeStructuralState(locale: SupportedAuthoringLocale): string { const completeness = this.content().localeCompleteness?.[locale]; if (completeness) return completeness.complete ? 'Complete' : completeness.present ? 'Incomplete' : 'Not provided'; return this.content().translations[locale] ? 'Provided' : 'Not provided'; }
  isReviewer(): boolean { const workspace = this.session.organizations().flatMap((organization) => organization.workspaces).find((candidate) => candidate.workspaceId === this.workspaceId()); return workspace?.roles.includes('reviewer') ?? false; }
  canApproveLocales(): boolean { return this.isReviewer() && this.currentDraftLocaleReviews().length > 0; }
  approvalLabel(): string { return this.currentDraftLocaleReviews().some((review) => review.reviewedAt) ? 'Reapprove current locales' : 'Approve / Reapprove current locales'; }
  approveLocales(): void { const locales = this.currentDraftLocaleReviews().map((review) => review.locale); if (!locales.length || !this.isReviewer()) return; const revision = this.store.document().revision; const identity = stableOperationIdentity({ revision, locales }); this.api.approveAuthoringLocales(this.workspaceId(), this.formId(), this.draftId(), revision, locales, this.store.operationKey(this.storageKey(), 'locale-review', identity)).subscribe({ next: (content) => { const selected = { ...content, locale: this.content().locale }; this.content.set(selected); this.populateContentEditors(selected); this.notice.set('Locale approvals recorded for the current revision.'); }, error: (error) => this.handleError(error) }); }
  saveGuidance(): void { let references: unknown; try { references = JSON.parse(this.referencesText); } catch { this.notice.set('Canonical references must be a JSON object.'); return; } const guidance = guidanceReferences(references); if (!guidance) { this.notice.set('Canonical references must be named {id,messageKey} entries with valid stable IDs and message keys.'); return; } this.preserveContentInputs = true; this.saveContentScope({ ...this.content(), guidance }, 'guidance', 'Schema-valid guidance references saved through the guidance scope.'); }
  saveTranslations(): void { const content = this.content(); const locale = content.locale; const current = content.translations[locale]; const guidance = guidanceReferences(content.guidance); if (!guidance) { this.notice.set('Save schema-valid guidance references before saving locale text.'); return; } const messages = { ...(current?.messages ?? {}) }; for (const [name, text] of Object.entries(this.governedText())) { const reference = guidance[name]; if (reference) messages[reference.messageKey] = text; } const bundle = { direction: current?.direction ?? (locale === 'ar' ? 'rtl' : 'ltr'), messages, ...(current?.pronunciations ? { pronunciations: current.pronunciations } : {}) }; this.preserveContentInputs = true; this.saveContentScope({ ...content, translations: { ...content.translations, [locale]: bundle } }, 'translations', 'Brief, detailed, glossary, Q&A, and narration text saved in the locale bundle.'); }
  toggleNarration(): void { if (this.audio) { this.audio.paused ? void this.resumeAudio() : this.pauseAudio(); return; } this.requestSpeech({ text: this.narrationText.trim() }); }
  startQuestionCapture(): void { const Recognition = browserSpeechRecognition(); if (!Recognition) { this.speechStatus.set('Browser speech recognition is unavailable. Use an enabled browser to ask governed questions.'); return; } this.cancelQuestionCapture(); this.capturedQuestion = ''; const recognition = new Recognition(); this.recognition = recognition; recognition.lang = this.content().locale; recognition.interimResults = true; recognition.continuous = false; recognition.onresult = (event) => { this.capturedQuestion = Array.from({ length: event.results.length - event.resultIndex }, (_, index) => event.results[event.resultIndex + index]?.[0]?.transcript ?? '').join('').trim(); };
    recognition.onerror = () => { this.speechCapturing.set(false); this.recognition = undefined; this.speechStatus.set('Browser speech capture was unavailable or cancelled.'); };
    recognition.onend = () => { const question = this.capturedQuestion; this.speechCapturing.set(false); this.recognition = undefined; if (question) this.requestSpeech({ question, scope: this.currentGuidanceScope() }); else this.speechStatus.set('No question was captured.'); };
    this.speechCapturing.set(true); this.speechStatus.set('Listening for a scoped governed question. Finish or cancel when ready.'); recognition.start(); }
  finishQuestionCapture(): void { this.recognition?.stop(); }
  cancelQuestionCapture(): void { const recognition = this.recognition; this.recognition = undefined; this.capturedQuestion = ''; this.speechCapturing.set(false); if (recognition) { recognition.onend = null; recognition.abort(); } }
  @HostListener('document:keydown', ['$event']) onKeydown(event: KeyboardEvent): void { const target = event.target as HTMLElement | null; if (target?.matches('input,textarea,[contenteditable="true"]')) return; if (!target?.closest('[data-testid="authoring-page"]')) return; if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'z') { event.preventDefault(); event.shiftKey ? this.redo() : this.undo(); } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'y') { event.preventDefault(); this.redo(); } }
  onTreeKeydown(event: KeyboardEvent): void { if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return; const items = [...document.querySelectorAll<HTMLButtonElement>('[data-authoring-id]')]; const index = items.findIndex((item) => item.dataset['authoringId'] === this.store.selectedId()); const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : Math.max(0, Math.min(items.length - 1, index + (event.key === 'ArrowDown' ? 1 : -1))); event.preventDefault(); items[next]?.focus(); items[next]?.click(); }

  private load(): void { this.api.authoringDocument(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (document) => { this.store.hydrate(this.storageKey(), document); this.resourceState.set('ready'); this.loadResources(); }, error: (error) => this.handleInitialLoadError(error) }); }
  /** Optional tools have independent capabilities; only document-load denials clear the draft. */
  private loadResources(): void { this.reloadHistory(); this.api.reusableComponents(this.workspaceId()).subscribe({ next: (components) => { if (this.resourceState() === 'ready') this.components.set(components); }, error: (error) => this.handleOptionalResourceError('Reusable components', error) }); this.api.authoringTheme(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (theme) => { if (this.resourceState() === 'ready') { this.theme.set(theme); this.themeTokensText = JSON.stringify(theme.tokens, null, 2); } }, error: (error) => this.handleOptionalResourceError('Theme', error) }); this.refreshContent(); this.api.authoringComments(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (comments) => { if (this.resourceState() === 'ready') this.comments.set(comments); }, error: (error) => this.handleOptionalResourceError('Comments', error) }); this.api.authoringPresence(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (presence) => { if (this.resourceState() === 'ready') this.presence.set(presence); }, error: (error) => this.handleOptionalResourceError('Presence', error) }); }
  private reloadHistory(): void { this.api.authoringHistory(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (history) => { if (this.resourceState() === 'ready') { this.store.history.set(history); this.store.persist(this.storageKey()); } }, error: () => undefined }); }
  private refreshCollaboration(): void { if (this.resourceState() !== 'ready') return; this.api.authoringComments(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (comments) => { if (this.resourceState() === 'ready') this.comments.set(comments); }, error: (error) => this.handleOptionalResourceError('Comments', error) }); this.api.authoringPresence(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (presence) => { if (this.resourceState() === 'ready') this.presence.set(presence); }, error: (error) => this.handleOptionalResourceError('Presence', error) }); this.api.updateAuthoringPresence(this.workspaceId(), this.formId(), this.draftId(), this.store.selectedId()).subscribe({ error: (error) => this.handleOptionalResourceError('Presence', error) }); }
  private localCommand(command: Parameters<AuthoringStore['apply']>[0]): void { this.store.apply(command, this.storageKey()); this.notice.set('Change added to local command history. Save to persist it for collaborators.'); }
  private selectedItem(): { id: string; title?: string; label?: string; pages?: unknown; sections?: unknown } | undefined { const id = this.store.selectedId(); for (const phase of this.store.document().phases) { if (phase.id === id) return phase; for (const page of phase.pages) { if (page.id === id) return page; for (const section of page.sections) { if (section.id === id) return section; const node = section.nodes.find((candidate) => candidate.id === id); if (node) return node; } } } return undefined; }
  private currentGuidanceScope(): GuidanceScope { const selected = this.store.selectedId(); for (const phase of this.store.document().phases) for (const page of phase.pages) { if (page.id === selected) return { pageId: page.id }; for (const section of page.sections) { if (section.id === selected) return { pageId: page.id, sectionId: section.id }; if (section.nodes.some((node) => node.id === selected)) return { pageId: page.id, sectionId: section.id, fieldId: selected ?? undefined }; } } return {}; }
  private containingSection(id: string | null): { id: string } | undefined { for (const phase of this.store.document().phases) for (const page of phase.pages) for (const section of page.sections) if (section.id === id || section.nodes.some((node) => node.id === id)) return section; return undefined; }
  private componentInsertionPath(sectionId: string): string | null { const definition = this.store.document().definition as { flow?: { phases?: { pages?: { sections?: { id?: string }[] }[] }[] } } | undefined; for (const [phaseIndex, phase] of (definition?.flow?.phases ?? []).entries()) for (const [pageIndex, page] of (phase.pages ?? []).entries()) { const sectionIndex = (page.sections ?? []).findIndex((section) => section.id === sectionId); if (sectionIndex >= 0) return `/flow/phases/${phaseIndex}/pages/${pageIndex}/sections/${sectionIndex}/nodes/-`; } return null; }
  private workspaceId(): string { return this.route.snapshot.paramMap.get('workspaceId') ?? ''; } private formId(): string { return this.route.snapshot.paramMap.get('formId') ?? ''; } private draftId(): string { return this.route.snapshot.paramMap.get('draftId') ?? ''; } private storageKey(): string { return authoringStorageKey(this.session.identity()?.accountId, this.workspaceId(), this.formId(), this.draftId()); }
  private saveContentScope(content: ContentSettings, scope: 'guidance' | 'translations', success: string): void { const revision = this.store.document().revision; const identity = stableOperationIdentity({ revision, scope, content: scope === 'guidance' ? content.guidance : content.translations }); this.api.updateAuthoringContent(this.workspaceId(), this.formId(), this.draftId(), revision, content, scope, this.store.operationKey(this.storageKey(), `content-${scope}`, identity)).subscribe({ next: (returned) => { const selected = { ...returned, locale: this.content().locale }; this.content.set(selected); this.populateContentEditors(selected); if (returned.document) this.store.acceptServer(returned.document, this.storageKey()); this.notice.set(success); }, error: (error) => this.handleError(error) }); }
  private populateContentEditors(content: ContentSettings): void { if (this.preserveContentInputs) return; const guidance = guidanceReferences(content.guidance); const messages = content.translations[content.locale]?.messages ?? {}; this.briefGuidanceText = translatedGuidance(messages, guidance?.brief); this.detailedGuidanceText = translatedGuidance(messages, guidance?.detailed); this.glossaryText = translatedJsonGuidance(messages, guidance?.glossary, '{}'); this.questionsAndAnswersText = translatedJsonGuidance(messages, guidance?.questionsAndAnswers, '[]'); this.narrationText = translatedGuidance(messages, guidance?.narration); this.referencesText = JSON.stringify(guidance ?? {}, null, 2); }
  private currentDraftLocaleReviews(): readonly LocaleReview[] { const revision = this.store.document().revision; return (this.content().localeReviews ?? []).filter((review) => review.sourceRevision === revision && review.status === 'DRAFT'); }
  private governedText(): Record<string, string> { return { brief: this.briefGuidanceText, detailed: this.detailedGuidanceText, glossary: this.glossaryText, questionsAndAnswers: this.questionsAndAnswersText, narration: this.narrationText }; }
  private requestSpeech(request: { text?: string; question?: string; scope?: GuidanceScope }): void { if (!request.text && !request.question) { this.speechStatus.set('Add governed narration or capture a governed question before requesting speech.'); return; } this.speechBusy.set(true); this.api.authoringSpeech(this.workspaceId(), this.formId(), this.draftId(), this.content().locale, request).subscribe({ next: (result) => this.applySpeechResult(result), error: (error) => { this.speechBusy.set(false); this.handleError(error); } }); }
  private applySpeechResult(result: SpeechResult): void { this.speechBusy.set(false); if (!result.available) { this.speechStatus.set(`Speech unavailable: ${result.code ?? 'SPEECH_UNAVAILABLE'}.`); return; } this.speechStatus.set('Speech is available.'); this.stopAudio(); if (result.audioBase64 && typeof Audio !== 'undefined') { const audio = new Audio(`data:${result.contentType ?? 'audio/mpeg'};base64,${result.audioBase64}`); this.audio = audio; audio.onended = () => { this.audio = undefined; this.speechPlaying.set(false); }; void audio.play().then(() => this.speechPlaying.set(true)).catch(() => { this.speechStatus.set('Speech audio is ready but playback was blocked by the browser.'); }); } }
  private pauseAudio(): void { this.audio?.pause(); this.speechPlaying.set(false); }
  private resumeAudio(): Promise<void> { return this.audio?.play().then(() => this.speechPlaying.set(true)).catch(() => this.speechStatus.set('Speech audio is ready but playback was blocked by the browser.')) ?? Promise.resolve(); }
  private stopAudio(): void { this.audio?.pause(); this.audio = undefined; this.speechPlaying.set(false); }
  private acceptRevision(document: AuthoringDocument): void { this.store.acceptServer(document, this.storageKey()); this.refreshContent(); }
  private refreshContent(): void { const selectedLocale = this.content().locale; this.api.authoringContent(this.workspaceId(), this.formId(), this.draftId()).subscribe({ next: (content) => { if (this.resourceState() !== 'ready') return; const selected = { ...content, locale: selectedLocale }; this.content.set(selected); this.populateContentEditors(selected); this.preserveContentInputs = false; }, error: (error) => this.handleOptionalResourceError('Locale review content', error) }); }
  private handleInitialLoadError(error: unknown): void { const response = error as HttpErrorResponse; if (response.status === 0) { this.store.hydrate(this.storageKey(), { ...this.store.document(), id: this.draftId() }); this.resourceState.set('offline'); return; } this.clearForAuthorization(response.status); }
  private handleOptionalResourceError(name: string, error: unknown): void { const response = error as HttpErrorResponse; if (response.status === 403) { this.notice.set(`${name} is unavailable for your current role; the draft remains available.`); return; } if (response.status === 401 || response.status === 419 || response.status === 440) { this.clearForAuthorization(response.status); return; } if (response.status !== 0) this.notice.set(`${name} could not be loaded.`); }
  private clearForAuthorization(status: number): void { if (status === 401 || status === 403) { this.clearResources(); this.resourceState.set('denied'); return; } if (status === 419 || status === 440) { this.clearResources(); this.resourceState.set('expired'); return; } this.resourceState.set('error'); }
  private clearResources(): void { this.store.clearCachedState(this.storageKey()); this.components.set([]); this.comments.set([]); this.presence.set([]); this.theme.set({ preset: 'Certinal', tokens: {}, locks: [], preflight: [] }); this.content.set({ locale: 'en', translations: {}, guidance: {}, localeReviews: [] }); }
  private handleError(error: unknown): void { const response = error as HttpErrorResponse; if (response.status === 409 || response.status === 412) { const body = response.error as { conflictId?: string; revision?: number; server?: unknown; client?: unknown }; const revision = body?.revision ?? this.store.document().revision; const server = body?.server === undefined ? this.store.document() : authoringDocument({ draftId: this.draftId(), revision, definition: body.server }); const client = body?.client === undefined ? this.store.document() : authoringDocument({ draftId: this.draftId(), revision, definition: body.client }); this.store.setConflict(client, server, body?.conflictId ?? '', 'This draft changed on the server. Choose a version to continue.', this.storageKey()); return; } if (response.status === 401 || response.status === 403 || response.status === 419 || response.status === 440) { this.clearForAuthorization(response.status); return; } this.notice.set(response.status === 0 ? 'The authoring service is unavailable.' : `Authoring request failed (${response.status || 'unknown'}).`); }
}

type GuidanceReference = { id: string; messageKey: string };

function guidanceReferences(value: unknown): Record<string, GuidanceReference> | null {
  const raw = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const references: Record<string, GuidanceReference> = {};
  for (const [name, entry] of Object.entries(raw)) {
    if (!/^[A-Za-z][A-Za-z0-9_-]{0,127}$/.test(name) || !entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    const reference = entry as Partial<GuidanceReference>;
    if (typeof reference.id !== 'string' || typeof reference.messageKey !== 'string' || !/^[A-Za-z][A-Za-z0-9_.-]{0,127}$/.test(reference.id) || !/^[a-z][a-z0-9_.-]{0,127}$/.test(reference.messageKey)) return null;
    references[name] = { id: reference.id, messageKey: reference.messageKey };
  }
  return references;
}

function translatedGuidance(messages: Record<string, string>, reference: GuidanceReference | undefined): string { return reference ? messages[reference.messageKey] ?? '' : ''; }
function translatedJsonGuidance(messages: Record<string, string>, reference: GuidanceReference | undefined, fallback: string): string {
  const value = translatedGuidance(messages, reference);
  if (!value) return fallback;
  try { JSON.parse(value); return value; } catch { return fallback; }
}

type GuidanceScope = { pageId?: string; sectionId?: string; fieldId?: string };
type BrowserSpeechResultEvent = { resultIndex: number; results: { length: number } & { [index: number]: { [index: number]: { transcript?: string } } } };
type BrowserSpeechRecognition = { lang: string; interimResults: boolean; continuous: boolean; onresult: ((event: BrowserSpeechResultEvent) => void) | null; onerror: (() => void) | null; onend: (() => void) | null; start(): void; stop(): void; abort(): void; };
function browserSpeechRecognition(): (new () => BrowserSpeechRecognition) | undefined { if (typeof window === 'undefined') return undefined; const browser = window as unknown as { SpeechRecognition?: new () => BrowserSpeechRecognition; webkitSpeechRecognition?: new () => BrowserSpeechRecognition }; return browser.SpeechRecognition ?? browser.webkitSpeechRecognition; }

function stableOperationIdentity(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableOperationIdentity).join(',')}]`;
  if (value && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${stableOperationIdentity(record[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}
